#include <stdint.h>

extern volatile uint64_t tohost;
extern int printf(const char *format, ...);

uint64_t _stack[512];
uint64_t * const _stack_top = _stack + 512;

static inline uint64_t read_cycles(void) {
    uint64_t c;
    asm volatile("rdcycle %0" : "=r"(c));
    return c;
}

int main(void) {
    printf("=== POSITIVE CONTROL TEST ===\n");

    uint64_t correct_cycles[20];
    uint64_t mispredict_cycles[20];

    // Measure 20 trials of correct prediction vs misprediction
    for (int trial = 0; trial < 20; trial++) {
        // Train branch to be taken
        volatile int train_val = 1;
        for (int i = 0; i < 20; i++) {
            asm volatile(
                "bne %0, x0, 1f\n"
                "nop\n"
                "1:\n"
                :
                : "r"(train_val)
            );
        }

        // Test correct prediction (taken)
        uint64_t t0, t1;
        asm volatile("nop; nop; nop; nop;");
        t0 = read_cycles();
        asm volatile(
            "bne %2, x0, 2f\n"
            "nop\n"
            "2:\n"
            :
            : "r"(train_val), "r"(train_val)
        );
        t1 = read_cycles();
        correct_cycles[trial] = t1 - t0;

        // Train branch to be taken again
        for (int i = 0; i < 20; i++) {
            asm volatile(
                "bne %0, x0, 3f\n"
                "nop\n"
                "3:\n"
                :
                : "r"(train_val)
            );
        }

        // Test misprediction (not taken)
        volatile int mispred_val = 0;
        asm volatile("nop; nop; nop; nop;");
        t0 = read_cycles();
        asm volatile(
            "bne %0, x0, 4f\n"
            "nop\n"
            "4:\n"
            :
            : "r"(mispred_val)
        );
        t1 = read_cycles();
        mispredict_cycles[trial] = t1 - t0;
    }

    printf("Correct prediction cycles (taken):\n");
    for (int i = 0; i < 20; i++) {
        printf(" %lu", correct_cycles[i]);
    }
    printf("\n");

    printf("Mispredicted cycles (not taken):\n");
    for (int i = 0; i < 20; i++) {
        printf(" %lu", mispredict_cycles[i]);
    }
    printf("\n");

    tohost = 1;
    while (1) {}
    return 0;
}

void _start(void) {
    asm volatile("mv sp, %0" :: "r"(_stack_top));
    main();
}

