#include <stdint.h>

extern volatile uint64_t tohost;

uint64_t _stack[512];
uint64_t * const _stack_top = _stack + 512;

#define UART0_BASE 0x54000000UL
#define UART_TXDATA ((volatile uint32_t *)(UART0_BASE + 0x0))

void uart_putc(char c) {
    *UART_TXDATA = (uint32_t)c;
}

void uart_puts(const char *s) {
    for (int i = 0; i < 500; i++) {
        if (!s[i]) break;
        uart_putc(s[i]);
    }
}

int main(void) {
    uart_puts("Hello UART\n");
    tohost = 1;
    while (1) {}
    return 0;
}

void _start(void) {
    asm volatile("mv sp, %0" :: "r"(_stack_top));
    main();
}

