#include <stdint.h>

extern volatile uint64_t tohost;
extern volatile uint64_t fromhost;

uint64_t _stack[512];
uint64_t * const _stack_top = _stack + 512;

#define SYS_write 64

static volatile uint64_t htif_payload[8] __attribute__((aligned(64)));

void print_str(const char *s, uint64_t len) {
    htif_payload[0] = SYS_write;
    htif_payload[1] = 1; // stdout
    htif_payload[2] = (uint64_t)s;
    htif_payload[3] = len;

    // Send request to fesvr via tohost
    tohost = (uint64_t)htif_payload;
    for (int i = 0; i < 500; i++) {
        if (fromhost != 0) {
            fromhost = 0;
            break;
        }
    }
}

int main(void) {
    char msg[] = "HELLO HTIF SYSCALL 64!\n";
    print_str(msg, sizeof(msg) - 1);
    tohost = 1;
    while (1) {}
    return 0;
}

void __attribute__((naked, section(".text.init"))) _start(void) {
    asm volatile(
        "la sp, _stack_top\n"
        "ld sp, 0(sp)\n"
        "tail main\n"
    );
}

