#include <stdint.h>

extern volatile uint64_t tohost;
extern volatile uint64_t fromhost;

uint64_t _stack[512];
uint64_t * const _stack_top = _stack + 512;

#define SYS_write 64
static volatile uint64_t htif_payload[8] __attribute__((aligned(64)));

static void print_str(const char *s, uint64_t len) {
    htif_payload[0] = SYS_write;
    htif_payload[1] = 1;
    htif_payload[2] = (uint64_t)s;
    htif_payload[3] = len;
    tohost = (uint64_t)htif_payload;
    for (int i = 0; i < 500; i++) {
        if (fromhost != 0) {
            fromhost = 0;
            break;
        }
    }
}

static void print_s(const char *s) {
    uint64_t l = 0;
    for (int i = 0; i < 500; i++) {
        if (!s[i]) break;
        l++;
    }
    print_str(s, l);
}

static void print_u64(uint64_t val) {
    char buf[24];
    int idx = 0;
    if (val == 0) {
        buf[idx++] = '0';
    } else {
        char tmp[24];
        int tlen = 0;
        for (int i = 0; i < 20; i++) {
            if (val == 0) break;
            tmp[tlen++] = '0' + (val % 10);
            val /= 10;
        }
        for (int i = tlen - 1; i >= 0; i--) {
            buf[idx++] = tmp[i];
        }
    }
    print_str(buf, idx);
}

static inline uint64_t read_cycles(void) {
    uint64_t c;
    asm volatile("rdcycle %0" : "=r"(c));
    return c;
}

int main(void) {
    print_s("=== POSITIVE CONTROL VERIFICATION ===\n");

    uint64_t correct_cycles[20];
    uint64_t mispredict_cycles[20];

    for (int trial = 0; trial < 20; trial++) {
        volatile int train_val = 1;
        // Train branch to be TAKEN
        for (int i = 0; i < 10; i++) {
            asm volatile(
                "bne %0, x0, 1f\n"
                "nop\n"
                "1:\n"
                :
                : "r"(train_val)
            );
        }

        // Test correctly predicted Taken branch
        uint64_t t0 = read_cycles();
        asm volatile(
            "bne %0, x0, 2f\n"
            "nop\n"
            "2:\n"
            :
            : "r"(train_val)
        );
        uint64_t t1 = read_cycles();
        correct_cycles[trial] = t1 - t0;

        // Train branch to be TAKEN again
        for (int i = 0; i < 10; i++) {
            asm volatile(
                "bne %0, x0, 3f\n"
                "nop\n"
                "3:\n"
                :
                : "r"(train_val)
            );
        }

        // Test mispredicted branch (actually NOT TAKEN)
        volatile int mispred_val = 0;
        t0 = read_cycles();
        asm volatile(
            "bne %0, x0, 4f\n"
            "nop\n"
            "4:\n"
            :
            : "r"(mispred_val)
        );
        t1 = read_cycles();
        mispredict_cycles[trial] = t1 - t0;
    }

    print_s("Correct prediction (taken) [20 trials]:\n");
    for (int i = 0; i < 20; i++) {
        print_s(" ");
        print_u64(correct_cycles[i]);
    }
    print_s("\n");

    print_s("Misprediction (not taken) [20 trials]:\n");
    for (int i = 0; i < 20; i++) {
        print_s(" ");
        print_u64(mispredict_cycles[i]);
    }
    print_s("\n");

    print_s("Positive control complete.\n");
    tohost = 1;
    while (1) {}
    return 0;
}

void __attribute__((naked, section(".text.init"))) _start(void) {
    asm volatile(
        "la sp, _stack_top\n"
        "ld sp, 0(sp)\n"
        "tail main\n"
    );
}

