    } else {
        char tmp[24];
        int tlen = 0;
        for (int i = 0; i < 20; i++) {
            if (val == 0) break;
            tmp[tlen++] = '0' + (val % 10);
            val /= 10;
        }
        for (int i = tlen - 1; i >= 0; i--) {
            buf[idx++] = tmp[i];
        }
    }
    print_str(buf, idx);
