// Function containing the target branch at a single fixed PC
__attribute__((noinline))
static uint64_t timed_branch(int cond) {
    uint64_t t0, t1;
    asm volatile(
        "nop; nop; nop; nop;\n"
        "rdcycle %0\n"
        "bne %2, x0, 1f\n"
        "nop; nop; nop; nop;\n"
        "1:\n"
        "rdcycle %1\n"
        : "=&r"(t0), "=&r"(t1)
        : "r"(cond)
    );
    return t1 - t0;
}

int main(void) {
    print_s("=== POSITIVE CONTROL WITH FIXED PC BRANCH ===\n");

    uint64_t correct_cycles[20];
    uint64_t mispredict_cycles[20];

    for (int trial = 0; trial < 20; trial++) {
        // Train branch to be TAKEN (cond = 1)
        for (int i = 0; i < 30; i++) {
            timed_branch(1);
        }

        // Measure correctly predicted branch (cond = 1)
        correct_cycles[trial] = timed_branch(1);

        // Train branch to be TAKEN again
        for (int i = 0; i < 30; i++) {
            timed_branch(1);
        }

        // Measure MISPREDICTED branch (cond = 0)
        mispredict_cycles[trial] = timed_branch(0);
    }

    print_s("Correct prediction (taken) [20 trials]:\n");
    for (int i = 0; i < 20; i++) {
        print_s(" ");
        print_u64(correct_cycles[i]);
    }
    print_s("\n");

    print_s("Misprediction (not taken) [20 trials]:\n");
    for (int i = 0; i < 20; i++) {
        print_s(" ");
        print_u64(mispredict_cycles[i]);
    }
    print_s("\n");

    print_s("Positive control complete.\n");
    tohost = 1;
    while (1) {}
    return 0;
}

