// Target probe branch function
__attribute__((noinline))
static uint64_t probe_branch(int cond) {
    uint64_t t0, t1;
    asm volatile(
        "nop; nop; nop; nop;\n"
        "rdcycle %0\n"
        ".balign 16\n"
        "bne %2, x0, 1f\n"
        "nop; nop; nop; nop;\n"
        "1:\n"
        "rdcycle %1\n"
        : "=&r"(t0), "=&r"(t1)
        : "r"(cond)
    );
    return t1 - t0;
}

// Function to train target branch to Strongly Taken (30 iterations)
__attribute__((noinline))
static void train_target_taken(void) {
    for (int i = 0; i < 30; i++) {
        probe_branch(1);
    }
}

// Function to step target branch Not-Taken twice with NO intervening branches (wrbypass HIT)
__attribute__((noinline))
static void step_target_hit(void) {
    // Two consecutive Not-Taken executions
    probe_branch(0);
    probe_branch(0);
}

// Function to step target branch Not-Taken twice WITH 3 intervening non-aliasing branches
__attribute__((noinline))
static void step_target_evict(void) {
    // Iteration 1: Target branch Not-Taken
    probe_branch(0);

    // 3 Intervening branches at distinct 16-byte aligned fetch packets
    volatile int dummy = 0;
    asm volatile(
        ".balign 16\n"
        "bne %0, x0, 1f\n"
        "nop\n"
        "1:\n"
        ".balign 16\n"
        "bne %0, x0, 2f\n"
        "nop\n"
        "2:\n"
        ".balign 16\n"
        "bne %0, x0, 3f\n"
        "nop\n"
        "3:\n"
        :
        : "r"(dummy)
    );

    // Iteration 2: Target branch Not-Taken
    probe_branch(0);
}

int main(void) {
    print_s("=== EXPERIMENT 1: WRBYPASS SEQUENTIAL TEST ===\n");

    uint64_t hit_probe[20];
    uint64_t evict_probe[20];

    // Measure Condition A: Hit (no eviction)
    for (int trial = 0; trial < 20; trial++) {
        // Train target branch to Strongly Taken
        train_target_taken();

        // Step twice Not-Taken (Hit condition)
        step_target_hit();

        // Probe target branch with Taken (cond = 1)
        hit_probe[trial] = probe_branch(1);
    }

    // Measure Condition B: Evict (3 intervening branches)
    for (int trial = 0; trial < 20; trial++) {
        // Train target branch to Strongly Taken
        train_target_taken();

        // Step twice Not-Taken with intervening branches (Evict condition)
        step_target_evict();

        // Probe target branch with Taken (cond = 1)
        evict_probe[trial] = probe_branch(1);
    }

    print_s("Condition A (Hit / No eviction) probe cycles [20 trials]:\n");
    for (int i = 0; i < 20; i++) {
        print_s(" ");
        print_u64(hit_probe[i]);
    }
    print_s("\n");

    print_s("Condition B (Evict / 3 intervening branches) probe cycles [20 trials]:\n");
    for (int i = 0; i < 20; i++) {
        print_s(" ");
        print_u64(evict_probe[i]);
    }
    print_s("\n");

    tohost = 1;
    while (1) {}
    return 0;
}

