#include <stdint.h>

extern volatile uint64_t tohost;
extern volatile uint64_t fromhost;

uint64_t _stack[512];
uint64_t * const _stack_top = _stack + 512;

#define SYS_write 64
static volatile uint64_t htif_payload[8] __attribute__((aligned(64)));

static void print_str(const char *s, uint64_t len) {
    for (int i = 0; i < 2000; i++) {
        if (tohost == 0) break;
    }
    htif_payload[0] = SYS_write;
    htif_payload[1] = 1;
    htif_payload[2] = (uint64_t)s;
    htif_payload[3] = len;
    tohost = (uint64_t)htif_payload;
    for (int i = 0; i < 2000; i++) {
        if (fromhost != 0) {
            fromhost = 0;
            break;
        }
    }
}

static void print_s(const char *s) {
    uint64_t l = 0;
    for (int i = 0; i < 500; i++) {
        if (!s[i]) break;
        l++;
    }
    print_str(s, l);
}

static void print_u64(uint64_t val) {
    char buf[24];
    int idx = 0;
    if (val == 0) {
        buf[idx++] = '0';
    } else {
        char tmp[24];
        int tlen = 0;
        for (int i = 0; i < 20; i++) {
            if (val == 0) break;
            tmp[tlen++] = '0' + (val % 10);
            val /= 10;
        }
        for (int i = tlen - 1; i >= 0; i--) {
            buf[idx++] = tmp[i];
        }
    }
    print_str(buf, idx);
}

// Fixed-PC target branch helper:
// When cond == 0, branch is NOT TAKEN (falls through).
// When cond == 1, branch is TAKEN (jumps to 1f).
// When do_time == 1, measures execution cycles.
__attribute__((noinline))
static uint64_t target_branch_op(int cond, int do_time) {
    uint64_t t0 = 0, t1 = 0;
    asm volatile(
        "nop; nop; nop; nop;\n"
        "beqz %4, 2f\n"
        "rdcycle %0\n"
        "2:\n"
        ".balign 16\n"
        "bnez %3, 1f\n"
        "nop; nop; nop; nop;\n"
        "1:\n"
        "beqz %4, 3f\n"
        "rdcycle %1\n"
        "3:\n"
        : "=&r"(t0), "=&r"(t1)
        : "0"(t0), "r"(cond), "r"(do_time)
    );
    return t1 - t0;
}

// Function to train target branch to Strongly Not-Taken (0)
__attribute__((noinline))
static void train_target_not_taken(void) {
    for (int i = 0; i < 15; i++) {
        target_branch_op(0, 0);
    }
}

// Mode A: ROB stall + 2 Taken executions with NO intervening branches (wrbypass HIT)
__attribute__((noinline))
static void run_mode_a(void) {
    // We execute target branch Taken twice in a tight loop with ROB head stall
    volatile uint64_t d0 = 12345678, d1 = 3;
    volatile int loop_cnt = 2;
    asm volatile(
        "mv t2, %2\n"       // loop_cnt = 2
        "mv t0, %0\n"
        "mv t1, %1\n"
        "10:\n"
        // ROB stall: 4 dependent divs (~40-60 cycles)
        "div t0, t0, t1\n"
        "div t0, t0, t1\n"
        "div t0, t0, t1\n"
        "div t0, t0, t1\n"
        // Target branch execution (Taken)
        // Calling target_branch_op(1, 0)
        :
        : "r"(d0), "r"(d1), "r"(loop_cnt)
        : "t0", "t1", "t2"
    );

    target_branch_op(1, 0);
    target_branch_op(1, 0);
}

// Mode B: ROB stall + 2 Taken executions WITH 3 intervening non-aliasing branches
__attribute__((noinline))
static void run_mode_b(void) {
    target_branch_op(1, 0);

    // 3 Intervening branches at distinct 16-byte aligned fetch packets
    volatile int dummy = 0;
    asm volatile(
        ".balign 16\n"
        "bne %0, x0, 11f\n"
        "nop\n"
        "11:\n"
        ".balign 16\n"
        "bne %0, x0, 12f\n"
        "nop\n"
        "12:\n"
        ".balign 16\n"
        "bne %0, x0, 13f\n"
        "nop\n"
        "13:\n"
        :
        : "r"(dummy)
    );

    target_branch_op(1, 0);
}

int main(void) {
    print_s("=== WRBYPASS PREDICTOR EXPERIMENT ===\n");

    uint64_t mode_a_cycles[20];
    uint64_t mode_b_cycles[20];

    // Evaluate Mode A (Hit)
    for (int trial = 0; trial < 20; trial++) {
        train_target_not_taken();
        run_mode_a();
        // Probe target branch Taken: if counter was incremented twice, it predicts Taken (fast)
        mode_a_cycles[trial] = target_branch_op(1, 1);
    }

    // Evaluate Mode B (Evict)
    for (int trial = 0; trial < 20; trial++) {
        train_target_not_taken();
        run_mode_b();
        // Probe target branch Taken: if counter was clobbered to 1, it predicts Not-Taken (slow mispredict)
        mode_b_cycles[trial] = target_branch_op(1, 1);
    }

    print_s("Mode A (wrbypass Hit) probe cycles [20 trials]:\n");
    for (int i = 0; i < 20; i++) {
        print_s(" ");
        print_u64(mode_a_cycles[i]);
    }
    print_s("\n");

    print_s("Mode B (wrbypass Evict) probe cycles [20 trials]:\n");
    for (int i = 0; i < 20; i++) {
        print_s(" ");
        print_u64(mode_b_cycles[i]);
    }
    print_s("\n");

    tohost = 1;
    while (1) {}
    return 0;
}

