extern volatile uint64_t tohost;
extern volatile uint64_t fromhost;

uint64_t _stack[512];
uint64_t * const _stack_top = _stack + 512;

#define SYS_write 64
static volatile uint64_t htif_payload[8] __attribute__((aligned(64)));

static void print_str(const char *s, uint64_t len) {
    for (int i = 0; i < 2000; i++) {
        if (tohost == 0) break;
    }
    htif_payload[0] = SYS_write;
    htif_payload[1] = 1;
    htif_payload[2] = (uint64_t)s;
    htif_payload[3] = len;
    tohost = (uint64_t)htif_payload;
    for (int i = 0; i < 2000; i++) {
        if (fromhost != 0) {
            fromhost = 0;
            break;
        }
    }
}

static void print_s(const char *s) {
    uint64_t l = 0;
    for (int i = 0; i < 500; i++) {
        if (!s[i]) break;
        l++;
    }
    print_str(s, l);
}

static void print_u64(uint64_t val) {
    char buf[24];
    int idx = 0;
    if (val == 0) {
        buf[idx++] = '0';
    } else {
        char tmp[24];
        int tlen = 0;
        for (int i = 0; i < 20; i++) {
            if (val == 0) break;
            tmp[tlen++] = '0' + (val % 10);
            val /= 10;
        }
        for (int i = tlen - 1; i >= 0; i--) {
            buf[idx++] = tmp[i];
        }
    }
    print_str(buf, idx);
}

// Global results arrays
#define NUM_TRIALS 20
static uint64_t pos_correct[NUM_TRIALS];
static uint64_t pos_mispredict[NUM_TRIALS];
static uint64_t cond_a_hit[NUM_TRIALS];
static uint64_t cond_b_evict[NUM_TRIALS];
static uint64_t cond_c_control[NUM_TRIALS];

// Harness function that executes:
// mode 0: Positive control - train Taken (10x), probe Taken
// mode 1: Positive control - train Taken (10x), probe Not-Taken
// mode 2: Condition A (Hit) - train Not-Taken (15x), 2x Taken with 0 intervening branches, probe Taken
// mode 3: Condition B (Evict) - train Not-Taken (15x), 2x Taken with 3 intervening branches, probe Taken
// mode 4: Condition C (Control) - train Not-Taken (15x), 2x Taken (0 interv), then 3 branches outside, probe Taken
__attribute__((noinline))
static uint64_t run_experiment_trial(int mode) {
    uint64_t cycles = 0;
    uint64_t t0 = 0, t1 = 0;

    // Reset registers
    register uint64_t reg_mode asm("a0") = mode;
    register uint64_t reg_cycles asm("a1") = 0;

    asm volatile(
        // Check mode:
        "li t0, 0\n"
        "beq a0, t0, .Lmode0\n"
        "li t0, 1\n"
        "beq a0, t0, .Lmode1\n"
        "li t0, 2\n"
        "beq a0, t0, .Lmode2\n"
        "li t0, 3\n"
        "beq a0, t0, .Lmode3\n"
        "j .Lmode4\n"

        // ==========================================
        // Mode 0: Positive Control Correct (Taken)
        // ==========================================
        ".Lmode0:\n"
        "li t2, 15\n"
        "100:\n"
        "li t3, 1\n"
        "bnez t3, 101f\n"
        "nop\n"
        "101:\n"
        "addi t2, t2, -1\n"
        "bnez t2, 100b\n"
        // Timed Probe (Taken)
        "nop; nop; nop; nop;\n"
        "rdcycle %0\n"
        "li t3, 1\n"
        "bnez t3, 102f\n"
        "nop; nop; nop; nop;\n"
        "102:\n"
        "rdcycle %1\n"
        "sub a1, %1, %0\n"
        "j .Ldone\n"

        // ==========================================
        // Mode 1: Positive Control Mispredict (Not-Taken)
        // ==========================================
        ".Lmode1:\n"
        "li t2, 15\n"
        "110:\n"
        "li t3, 1\n"
        "bnez t3, 111f\n"
        "nop\n"
        "111:\n"
        "addi t2, t2, -1\n"
        "bnez t2, 110b\n"
        // Timed Probe (Not-Taken)
        "nop; nop; nop; nop;\n"
        "rdcycle %0\n"
        "li t3, 0\n"
        "bnez t3, 112f\n"
        "nop; nop; nop; nop;\n"
        "112:\n"
        "rdcycle %1\n"
        "sub a1, %1, %0\n"
        "j .Ldone\n"

        // ==========================================
        // Mode 2: Condition A (wrbypass Hit)
        // ==========================================
        ".Lmode2:\n"
        // Train target branch Not-Taken (15 iterations)
        "li t2, 15\n"
        "120:\n"
        "li t3, 0\n"
        "bnez t3, 121f\n"
        "nop\n"
        "121:\n"
        "addi t2, t2, -1\n"
        "bnez t2, 120b\n"

        // 2-iteration Taken execution with ROB stall
        "li t4, 999999\n"
        "li t5, 7\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "li t2, 2\n"
        "122:\n"
        ".balign 16\n"
        "li t3, 1\n"
        "bnez t3, 123f\n"
        "nop\n"
        "123:\n"
        "addi t2, t2, -1\n"
        "bnez t2, 122b\n"

        // Probe target branch Taken
        "nop; nop; nop; nop;\n"
        "rdcycle %0\n"
        "li t3, 1\n"
        "bnez t3, 124f\n"
        "nop; nop; nop; nop;\n"
        "124:\n"
        "rdcycle %1\n"
        "sub a1, %1, %0\n"
        "j .Ldone\n"

        // ==========================================
        // Mode 3: Condition B (wrbypass Evict)
        // ==========================================
        ".Lmode3:\n"
        // Train target branch Not-Taken (15 iterations)
        "li t2, 15\n"
        "130:\n"
        "li t3, 0\n"
        "bnez t3, 131f\n"
        "nop\n"
        "131:\n"
        "addi t2, t2, -1\n"
        "bnez t2, 130b\n"

        // 2-iteration Taken execution with ROB stall and 3 intervening branches
        "li t4, 999999\n"
        "li t5, 7\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "li t2, 2\n"
        "132:\n"
        ".balign 16\n"
        "li t3, 1\n"
        "bnez t3, 133f\n"
        "nop\n"
        "133:\n"
        // 3 intervening branches at distinct 16-byte packets:
        ".balign 16\n"
        "bne x0, x0, 134f\n"
        "nop\n"
        "134:\n"
        ".balign 16\n"
        "bne x0, x0, 135f\n"
        "nop\n"
        "135:\n"
        ".balign 16\n"
        "bne x0, x0, 136f\n"
        "nop\n"
        "136:\n"
        "addi t2, t2, -1\n"
        "bnez t2, 132b\n"

        // Probe target branch Taken
        "nop; nop; nop; nop;\n"
        "rdcycle %0\n"
        "li t3, 1\n"
        "bnez t3, 137f\n"
        "nop; nop; nop; nop;\n"
        "137:\n"
        "rdcycle %1\n"
        "sub a1, %1, %0\n"
        "j .Ldone\n"

        // ==========================================
        // Mode 4: Condition C (Outside-Window Control)
        // ==========================================
        ".Lmode4:\n"
        // Train target branch Not-Taken (15 iterations)
        "li t2, 15\n"
        "140:\n"
        "li t3, 0\n"
        "bnez t3, 141f\n"
        "nop\n"
        "141:\n"
        "addi t2, t2, -1\n"
        "bnez t2, 140b\n"

        // 2-iteration Taken execution with ROB stall (0 intervening branches)
        "li t4, 999999\n"
        "li t5, 7\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "li t2, 2\n"
        "142:\n"
        ".balign 16\n"
        "li t3, 1\n"
        "bnez t3, 143f\n"
        "nop\n"
        "143:\n"
        "addi t2, t2, -1\n"
        "bnez t2, 142b\n"

        // Pipeline settling NOPs
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"

        // Intervening branches executed AFTER loop finishes
        ".balign 16\n"
        "bne x0, x0, 144f\n"
        "nop\n"
        "144:\n"
        ".balign 16\n"
        "bne x0, x0, 145f\n"
        "nop\n"
        "145:\n"
        ".balign 16\n"
        "bne x0, x0, 146f\n"
        "nop\n"
        "146:\n"

        // Probe target branch Taken
        "nop; nop; nop; nop;\n"
        "rdcycle %0\n"
        "li t3, 1\n"
        "bnez t3, 147f\n"
        "nop; nop; nop; nop;\n"
        "147:\n"
        "rdcycle %1\n"
        "sub a1, %1, %0\n"

        ".Ldone:\n"
        : "=&r"(t0), "=&r"(t1), "+r"(reg_cycles)
        : "r"(reg_mode)
        : "t0", "t1", "t2", "t3", "t4", "t5", "memory"
    );

    cycles = reg_cycles;
    return cycles;
}

int main(void) {
    print_s("=== BOOM BRANCH PREDICTOR WRBYPASS EXPERIMENT ===\n\n");

    // 1. Positive Control: Correct vs Mispredict
    for (int i = 0; i < NUM_TRIALS; i++) {
        pos_correct[i] = run_experiment_trial(0);
        pos_mispredict[i] = run_experiment_trial(1);
    }

    // 2. Attack Scenario: Condition A (Hit) vs Condition B (Evict)
    for (int i = 0; i < NUM_TRIALS; i++) {
        cond_a_hit[i] = run_experiment_trial(2);
        cond_b_evict[i] = run_experiment_trial(3);
    }

    // 3. Negative Control: Condition C (Outside-window)
    for (int i = 0; i < NUM_TRIALS; i++) {
        cond_c_control[i] = run_experiment_trial(4);
    }

    // Print all raw distributions
    print_s("Positive Control - Correct Prediction [20 trials]:\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        print_s(" ");
        print_u64(pos_correct[i]);
    }
    print_s("\n\n");

    print_s("Positive Control - Deliberate Misprediction [20 trials]:\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        print_s(" ");
        print_u64(pos_mispredict[i]);
    }
    print_s("\n\n");

    print_s("Condition A - wrbypass Hit (0 intervening branches) [20 trials]:\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        print_s(" ");
        print_u64(cond_a_hit[i]);
    }
    print_s("\n\n");

    print_s("Condition B - wrbypass Evict (3 intervening branches) [20 trials]:\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        print_s(" ");
        print_u64(cond_b_evict[i]);
    }
    print_s("\n\n");

    print_s("Condition C - Negative Control (intervening branches outside window) [20 trials]:\n");
    for (int i = 0; i < NUM_TRIALS; i++) {
        print_s(" ");
        print_u64(cond_c_control[i]);
    }
    print_s("\n\n");

    print_s("=== EXPERIMENT RUN COMPLETE ===\n");
    tohost = 1;
    while (1) {}
    return 0;
}

