// Low-level test kernel using a single, unified target branch at .Ltarget_branch
// mode 0: Positive control - Train Taken (15x), Probe Taken (expect FAST)
// mode 1: Positive control - Train Taken (15x), Probe Not-Taken (expect SLOW)
// mode 2: Condition A (Hit) - Train Not-Taken (15x), 2x In-Flight Taken (0 interv), Probe Taken
// mode 3: Condition B (Evict) - Train Not-Taken (15x), 2x In-Flight Taken (3 interv), Probe Taken
// mode 4: Condition C (Control) - Train Not-Taken (15x), 2x In-Flight Taken, then 3 interv outside, Probe Taken
__attribute__((noinline))
static uint64_t test_kernel(int mode) {
    register uint64_t reg_mode asm("a0") = mode;
    register uint64_t reg_res asm("a0");

    asm volatile(
        "li t0, 0\n"
        "beq a0, t0, .Lpos_correct\n"
        "li t0, 1\n"
        "beq a0, t0, .Lpos_mispredict\n"
        "li t0, 2\n"
