// Function to measure probe latency after N taken steps (following 15 not-taken steps)
__attribute__((noinline))
static uint64_t calibrate_step(int n_taken_steps) {
    register uint64_t reg_n asm("a0") = n_taken_steps;
    register uint64_t reg_res asm("a0");

    asm volatile(
        // Train Not-Taken 15x
        "li a2, 15\n"
        "1:\n"
        "li t3, 0\n"
        "jal t6, .Ltarget_branch\n"
        "addi a2, a2, -1\n"
        "bnez a2, 1b\n"

        // Execute n_taken_steps with Taken
        "mv a2, a0\n"
        "beqz a2, 3f\n"
        "2:\n"
        "li t3, 1\n"
        "jal t6, .Ltarget_branch\n"
        "addi a2, a2, -1\n"
        "bnez a2, 2b\n"
        "3:\n"

        // Drain pipeline
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"

        // Timed Probe: Taken (t3 = 1)
        "li t3, 1\n"
        "rdcycle a4\n"
        "jal t6, .Ltarget_branch\n"
        "rdcycle a5\n"
        "sub a0, a5, a4\n"
        "j .Ldone\n"

        ".balign 16\n"
        ".Ltarget_branch:\n"
        "bnez t3, .Ltb_taken\n"
        "nop\n"
        ".Ltb_taken:\n"
        "jr t6\n"

        ".Ldone:\n"
        : "=r"(reg_res)
        : "0"(reg_n)
        : "t3", "t6", "a2", "a4", "a5", "memory"
    );

    return reg_res;
}

int main(void) {
    print_s("=== CALIBRATION OF PREDICTOR THRESHOLD ===\n");

    for (int steps = 0; steps <= 4; steps++) {
        print_s("Steps Taken = ");
        print_u64(steps);
        print_s(": ");
        for (int trial = 0; trial < 10; trial++) {
            uint64_t c = calibrate_step(steps);
            print_s(" ");
            print_u64(c);
        }
        print_s("\n");
    }

    tohost = 1;
    while (1) {}
    return 0;
}

