uint64_t _stack[512];
uint64_t * const _stack_top = _stack + 512;

#define SYS_write 64
static volatile uint64_t htif_payload[8] __attribute__((aligned(64)));

static void print_str(const char *s, uint64_t len) {
    for (int i = 0; i < 20000; i++) {
        if (tohost == 0) break;
    }
    htif_payload[0] = SYS_write;
    htif_payload[1] = 1;
    htif_payload[2] = (uint64_t)s;
    htif_payload[3] = len;
    tohost = (uint64_t)htif_payload;
    for (int i = 0; i < 20000; i++) {
        if (fromhost != 0) {
            fromhost = 0;
            break;
        }
    }
}

static void print_s(const char *s) {
    uint64_t l = 0;
    for (int i = 0; i < 500; i++) {
        if (!s[i]) break;
        l++;
    }
    print_str(s, l);
}

static void print_u64(uint64_t val) {
    char buf[24];
    int idx = 0;
    if (val == 0) {
        buf[idx++] = '0';
    } else {
        char tmp[24];
        int tlen = 0;
        for (int i = 0; i < 20; i++) {
            if (val == 0) break;
            tmp[tlen++] = '0' + (val % 10);
            val /= 10;
        }
        for (int i = tlen - 1; i >= 0; i--) {
            buf[idx++] = tmp[i];
        }
    }
    print_str(buf, idx);
}

// Function to measure probe latency after unrolled training
__attribute__((noinline))
static uint64_t test_unrolled(int train_taken, int probe_taken) {
    register uint64_t r_train asm("a0") = train_taken;
    register uint64_t r_probe asm("a1") = probe_taken;
    register uint64_t reg_res asm("a0");

    asm volatile(
        "mv t3, a0\n" // t3 = train condition

        // 16 completely unrolled training calls with ZERO conditional loop branches
        "jal t6, .Ltb\n"
        "jal t6, .Ltb\n"
        "jal t6, .Ltb\n"
        "jal t6, .Ltb\n"
        "jal t6, .Ltb\n"
        "jal t6, .Ltb\n"
        "jal t6, .Ltb\n"
        "jal t6, .Ltb\n"
        "jal t6, .Ltb\n"
        "jal t6, .Ltb\n"
        "jal t6, .Ltb\n"
        "jal t6, .Ltb\n"
        "jal t6, .Ltb\n"
        "jal t6, .Ltb\n"
        "jal t6, .Ltb\n"
        "jal t6, .Ltb\n"

        // Pipeline settling NOPs
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"

        // Set probe condition
        "mv t3, a1\n"
        "rdcycle a4\n"
        "jal t6, .Ltb\n"
        "rdcycle a5\n"
        "sub a0, a5, a4\n"
        "j .Lexit\n"

        ".balign 16\n"
        ".Ltb:\n"
        "bnez t3, .Ltb_dest\n"
        "nop\n"
        ".Ltb_dest:\n"
        "jr t6\n"

        ".Lexit:\n"
        : "=r"(reg_res)
        : "0"(r_train), "r"(r_probe)
        : "t3", "t6", "a4", "a5", "memory"
    );

    return reg_res;
}

int main(void) {
