        // Normalize GHR with 16 consecutive always-taken BEQ branches
        "beq x0, x0, 101f\n 101:\n beq x0, x0, 102f\n 102:\n"
        "beq x0, x0, 103f\n 103:\n beq x0, x0, 104f\n 104:\n"
