__attribute__((noinline))
static uint64_t test_step_count(int num_taken_steps) {
    register uint64_t r_steps asm("a0") = num_taken_steps;
    register uint64_t reg_res asm("a0");

    asm volatile(
        // Normalize GHR with 16 taken branches
        "beq x0, x0, 201f\n 201:\n beq x0, x0, 202f\n 202:\n"
        "beq x0, x0, 203f\n 203:\n beq x0, x0, 204f\n 204:\n"
        "beq x0, x0, 205f\n 205:\n beq x0, x0, 206f\n 206:\n"
        "beq x0, x0, 207f\n 207:\n beq x0, x0, 208f\n 208:\n"
        "beq x0, x0, 209f\n 209:\n beq x0, x0, 210f\n 210:\n"
        "beq x0, x0, 211f\n 211:\n beq x0, x0, 212f\n 212:\n"
        "beq x0, x0, 213f\n 213:\n beq x0, x0, 214f\n 214:\n"
        "beq x0, x0, 215f\n 215:\n beq x0, x0, 216f\n 216:\n"

        // Train Not-Taken 16 times
        "li t3, 0\n"
        "jal t6, .Ltb3\n jal t6, .Ltb3\n jal t6, .Ltb3\n jal t6, .Ltb3\n"
        "jal t6, .Ltb3\n jal t6, .Ltb3\n jal t6, .Ltb3\n jal t6, .Ltb3\n"
        "jal t6, .Ltb3\n jal t6, .Ltb3\n jal t6, .Ltb3\n jal t6, .Ltb3\n"
        "jal t6, .Ltb3\n jal t6, .Ltb3\n jal t6, .Ltb3\n jal t6, .Ltb3\n"

        // Perform num_taken_steps
        "li t0, 0\n"
        "beq a0, t0, .Ldo_probe\n"
        "li t0, 1\n"
        "beq a0, t0, .Lone_step\n"

        // Two steps:
        "li t3, 1\n"
        "jal t6, .Ltb3\n"
        "nop; nop; nop; nop;\n"
        "jal t6, .Ltb3\n"
        "j .Ldo_probe\n"

        ".Lone_step:\n"
        "li t3, 1\n"
        "jal t6, .Ltb3\n"

        ".Ldo_probe:\n"
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n"
        "jal t6, .Ltb3\n"
        "rdcycle a5\n"
        "sub a0, a5, a4\n"
        "j .Ldone3\n"

        ".balign 16\n"
        ".Ltb3:\n"
        "bnez t3, .Ltb3_dest\n"
        "nop\n"
        ".Ltb3_dest:\n"
        "jr t6\n"

        ".Ldone3:\n"
        : "=r"(reg_res)
        : "0"(r_steps)
        : "t0", "t3", "t6", "a4", "a5", "memory"
    );

    return reg_res;
}

int main(void) {
    print_s("=== STEP COUNT THRESHOLD TEST ===\n");

    print_s("0 Steps Taken (Pure Not-Taken baseline): ");
    for (int i = 0; i < 10; i++) {
        uint64_t c = test_step_count(0);
        print_s(" ");
        print_u64(c);
    }
    print_s("\n");

    print_s("1 Step Taken:                           ");
    for (int i = 0; i < 10; i++) {
