        print_s(" ");
        print_u64(c);
    }
    print_s("\n");

    print_s("2 Steps Taken:                          ");
    for (int i = 0; i < 10; i++) {
        uint64_t c = test_step_count(2);
        print_s(" ");
        print_u64(c);
    }
    print_s("\n");

    tohost = 1;
    while (1) {}
    return 0;
}

