// Low-level test kernel:
// mode 0: Positive Control - Correct Prediction (Train Taken 16x, Probe Taken)
// mode 1: Positive Control - Deliberate Misprediction (Train Taken 16x, Probe Not-Taken)
// mode 2: Condition A (Hit) - Train Taken 16x, 2 in-flight Not-Taken updates (0 interv), Probe Taken
// mode 3: Condition B (Evict) - Train Taken 16x, 2 in-flight Not-Taken updates (3 interv), Probe Taken
// mode 4: Condition C (Control) - Train Taken 16x, 2 in-flight Not-Taken, 3 interv outside, Probe Taken
__attribute__((noinline))
static uint64_t run_core_kernel(int mode) {
    register uint64_t r_mode asm("a0") = mode;
    register uint64_t reg_res asm("a0");

    asm volatile(
        // Normalize GHR with 16 taken branches
        "beq x0, x0, 401f\n 401:\n beq x0, x0, 402f\n 402:\n"
        "beq x0, x0, 403f\n 403:\n beq x0, x0, 404f\n 404:\n"
