        "beq x0, x0, 409f\n 409:\n beq x0, x0, 410f\n 410:\n"
        "beq x0, x0, 411f\n 411:\n beq x0, x0, 412f\n 412:\n"
        "beq x0, x0, 413f\n 413:\n beq x0, x0, 414f\n 414:\n"
        "beq x0, x0, 415f\n 415:\n beq x0, x0, 416f\n 416:\n"

        // Train target branch Taken 16 times
        "li t3, 1\n"
        "jal t6, .Ltarget_b\n jal t6, .Ltarget_b\n jal t6, .Ltarget_b\n jal t6, .Ltarget_b\n"
        "jal t6, .Ltarget_b\n jal t6, .Ltarget_b\n jal t6, .Ltarget_b\n jal t6, .Ltarget_b\n"
        "jal t6, .Ltarget_b\n jal t6, .Ltarget_b\n jal t6, .Ltarget_b\n jal t6, .Ltarget_b\n"
        "jal t6, .Ltarget_b\n jal t6, .Ltarget_b\n jal t6, .Ltarget_b\n jal t6, .Ltarget_b\n"

        // Branch based on mode:
        "li t0, 0\n"
        "beq a0, t0, .Lpos_cor\n"
        "li t0, 1\n"
        "beq a0, t0, .Lpos_mis\n"
        "li t0, 2\n"
        "beq a0, t0, .Lcase_a\n"
        "li t0, 3\n"
        "beq a0, t0, .Lcase_b\n"
        "j .Lcase_c\n"

        // Mode 0: Positive Control Correct (Probe Taken)
        ".Lpos_cor:\n"
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n"
        "jal t6, .Ltarget_b\n"
        "rdcycle a5\n"
        "sub a0, a5, a4\n"
        "j .Lkernel_exit\n"

        // Mode 1: Positive Control Mispredict (Probe Not-Taken)
        ".Lpos_mis:\n"
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 0\n"
        "rdcycle a4\n"
        "jal t6, .Ltarget_b\n"
        "rdcycle a5\n"
        "sub a0, a5, a4\n"
        "j .Lkernel_exit\n"

        // Mode 2: Condition A (Hit: 2 in-flight Not-Taken updates, 0 intervening)
        ".Lcase_a:\n"
        // ROB stall: 4 dependent divs
        "li t4, 999999\n"
        "li t5, 7\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "li a2, 2\n"
        "501:\n"
        "li t3, 0\n" // Not-Taken update
        "jal t6, .Ltarget_b\n"
        "addi a2, a2, -1\n"
        "bnez a2, 501b\n"
        // Timed Probe: Taken (t3 = 1)
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n"
        "jal t6, .Ltarget_b\n"
        "rdcycle a5\n"
        "sub a0, a5, a4\n"
        "j .Lkernel_exit\n"

        // Mode 3: Condition B (Evict: 2 in-flight Not-Taken updates, 3 intervening)
        ".Lcase_b:\n"
        // ROB stall: 4 dependent divs
        "li t4, 999999\n"
        "li t5, 7\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "li a2, 2\n"
        "502:\n"
        "li t3, 0\n" // Not-Taken update
        "jal t6, .Ltarget_b\n"
        // 3 intervening branches at distinct 16-byte aligned fetch packets
        ".balign 16\n"
        "bne x0, x0, 503f\n"
        "nop\n"
        "503:\n"
        ".balign 16\n"
        "bne x0, x0, 504f\n"
        "nop\n"
        "504:\n"
        ".balign 16\n"
        "bne x0, x0, 505f\n"
        "nop\n"
        "505:\n"
        "addi a2, a2, -1\n"
        "bnez a2, 502b\n"
        // Timed Probe: Taken (t3 = 1)
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n"
        "jal t6, .Ltarget_b\n"
        "rdcycle a5\n"
        "sub a0, a5, a4\n"
        "j .Lkernel_exit\n"

        // Mode 4: Condition C (Negative Control: 2 in-flight Not-Taken, 3 interv outside)
        ".Lcase_c:\n"
        // ROB stall: 4 dependent divs
        "li t4, 999999\n"
        "li t5, 7\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "li a2, 2\n"
        "506:\n"
        "li t3, 0\n" // Not-Taken update
        "jal t6, .Ltarget_b\n"
        "addi a2, a2, -1\n"
        "bnez a2, 506b\n"
        // Settle pipeline
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        // Intervening branches executed outside window
        ".balign 16\n"
        "bne x0, x0, 507f\n"
        "nop\n"
        "507:\n"
        ".balign 16\n"
        "bne x0, x0, 508f\n"
        "nop\n"
        "508:\n"
        ".balign 16\n"
        "bne x0, x0, 509f\n"
        "nop\n"
        "509:\n"
        // Timed Probe: Taken (t3 = 1)
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n"
        "jal t6, .Ltarget_b\n"
        "rdcycle a5\n"
        "sub a0, a5, a4\n"
        "j .Lkernel_exit\n"

        // Target Branch
        ".balign 16\n"
        ".Ltarget_b:\n"
        "bnez t3, .Ltb_take\n"
        "nop\n"
        ".Ltb_take:\n"
        "jr t6\n"

        ".Lkernel_exit:\n"
        : "=r"(reg_res)
        : "0"(r_mode)
        : "t0", "t3", "t4", "t5", "t6", "a2", "a4", "a5", "memory"
    );

    return reg_res;
}

