}

static void print_u64(uint64_t val) {
    char buf[24];
    int idx = 0;
    if (val == 0) {
        buf[idx++] = '0';
    } else {
        char tmp[24];
        int tlen = 0;
        for (int i = 0; i < 20; i++) {
            if (val == 0) break;
            tmp[tlen++] = '0' + (val % 10);
            val /= 10;
        }
        for (int i = tlen - 1; i >= 0; i--) {
            buf[idx++] = tmp[i];
        }
    }
    print_str(buf, idx);
}

__attribute__((noinline))
static uint64_t test_symmetric_train(int n_taken_train, int n_nt_steps) {
    register uint64_t r_taken asm("a0") = n_taken_train;
    register uint64_t r_nt asm("a1") = n_nt_steps;
    register uint64_t reg_res asm("a0");

    asm volatile(
        // Normalize GHR
        "beq x0, x0, 701f\n 701:\n beq x0, x0, 702f\n 702:\n"
        "beq x0, x0, 703f\n 703:\n beq x0, x0, 704f\n 704:\n"
        "beq x0, x0, 705f\n 705:\n beq x0, x0, 706f\n 706:\n"
        "beq x0, x0, 707f\n 707:\n beq x0, x0, 708f\n 708:\n"

        // Train Not-Taken 4 times first (to scrub prior trial Taken state)
        "li t3, 0\n"
        "jal t6, .Ltb_sym\n jal t6, .Ltb_sym\n jal t6, .Ltb_sym\n jal t6, .Ltb_sym\n"

        // Train Taken exactly n_taken_train times (e.g. 2 times)
        "li t3, 1\n"
        "jal t6, .Ltb_sym\n jal t6, .Ltb_sym\n"

        // Step Not-Taken n_nt_steps times:
        "li t0, 0\n"
        "beq a1, t0, .Lsym_probe\n"
        "li t0, 1\n"
        "beq a1, t0, .Lsym_one_step\n"

        // 2 Not-Taken steps:
        "li t3, 0\n"
        "jal t6, .Ltb_sym\n nop; nop;\n jal t6, .Ltb_sym\n"
        "j .Lsym_probe\n"

        ".Lsym_one_step:\n"
        "li t3, 0\n"
        "jal t6, .Ltb_sym\n"

        ".Lsym_probe:\n"
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        // Probe Taken
        "li t3, 1\n"
        "rdcycle a4\n"
        "jal t6, .Ltb_sym\n"
        "rdcycle a5\n"
        "sub a0, a5, a4\n"
        "j .Lsym_done\n"

        ".balign 16\n"
        ".Ltb_sym:\n"
        "bnez t3, .Ltb_sym_dest\n"
        "nop\n"
        ".Ltb_sym_dest:\n"
        "jr t6\n"

        ".Lsym_done:\n"
        : "=r"(reg_res)
        : "0"(r_taken), "r"(r_nt)
        : "t0", "t3", "t6", "a4", "a5", "memory"
    );

    return reg_res;
}

int main(void) {
    print_s("=== SYMMETRIC TRAINING REPRODUCIBILITY TEST ===\n");

    print_s("0 NT steps (Baseline Taken): ");
    for (int i = 0; i < 15; i++) {
        uint64_t c = test_symmetric_train(2, 0);
        print_s(" ");
        print_u64(c);
    }
    print_s("\n");

    print_s("1 NT step (Weak Taken):      ");
    for (int i = 0; i < 15; i++) {
        uint64_t c = test_symmetric_train(2, 1);
        print_s(" ");
        print_u64(c);
    }
    print_s("\n");

    print_s("2 NT steps (Flipped to NT):  ");
    for (int i = 0; i < 15; i++) {
        uint64_t c = test_symmetric_train(2, 2);
        print_s(" ");
        print_u64(c);
    }
    print_s("\n");

    tohost = 1;
    while (1) {}
    return 0;
}

