// Function to measure probe latency with a unique trial GHR
__attribute__((noinline))
static uint64_t test_with_trial_ghr(int trial_id, int probe_taken) {
    register uint64_t r_trial asm("a0") = trial_id;
    register uint64_t r_probe asm("a1") = probe_taken;
    register uint64_t reg_res asm("a0");

    asm volatile(
        // Inject trial_id unique branches into GHR to guarantee TAGE miss
        "mv t0, a0\n"
        "andi t0, t0, 15\n"
        "beqz t0, 802f\n"
        "801:\n"
        "beq x0, x0, 803f\n"
        "803:\n"
        "addi t0, t0, -1\n"
        "bnez t0, 801b\n"
        "802:\n"

        // Train target branch Taken 8 times
        "li t3, 1\n"
        "jal t6, .Ltb_u\n jal t6, .Ltb_u\n jal t6, .Ltb_u\n jal t6, .Ltb_u\n"
        "jal t6, .Ltb_u\n jal t6, .Ltb_u\n jal t6, .Ltb_u\n jal t6, .Ltb_u\n"

        // Pipeline settling NOPs
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"

        // Probe branch with r_probe (a1)
        "mv t3, a1\n"
        "rdcycle a4\n"
        "jal t6, .Ltb_u\n"
        "rdcycle a5\n"
        "sub a0, a5, a4\n"
        "j .Lu_exit\n"

        ".balign 16\n"
        ".Ltb_u:\n"
        "bnez t3, .Ltb_u_dest\n"
        "nop\n"
        ".Ltb_u_dest:\n"
        "jr t6\n"

        ".Lu_exit:\n"
        : "=r"(reg_res)
        : "0"(r_trial), "r"(r_probe)
        : "t0", "t3", "t6", "a4", "a5", "memory"
    );

    return reg_res;
}

int main(void) {
    print_s("=== BIM EVALUATION WITH TRIAL-SPECIFIC GHR ===\n");

    // Case 1: Train Taken, Probe Taken (Correct prediction -> ~27 cycles)
    print_s("Train Taken, Probe Taken [20 trials]:\n");
    for (int trial = 0; trial < 20; trial++) {
        uint64_t c = test_with_trial_ghr(trial, 1);
