// Low-level test kernel:
// Mode 0: Positive Control Correct (Train Taken 8x, Probe Taken) -> expect ~27
// Mode 1: Positive Control Mispredict (Train Not-Taken 8x, Probe Taken) -> expect ~36
// Mode 2: Condition A (Hit): Train Not-Taken 8x, 2 in-flight Taken (0 interv), Probe Taken
// Mode 3: Condition B (Evict): Train Not-Taken 8x, 2 in-flight Taken (3 interv), Probe Taken
// Mode 4: Condition C (Control): Train Not-Taken 8x, 2 in-flight Taken, 3 interv outside, Probe Taken
__attribute__((noinline))
static uint64_t run_kernel_e(int mode) {
    register uint64_t r_mode asm("a0") = mode;
    register uint64_t reg_res asm("a0");

    asm volatile(
        "li t0, 0\n"
        "beq a0, t0, .Le_pos_cor\n"
        "li t0, 1\n"
        "beq a0, t0, .Le_pos_mis\n"
        "li t0, 2\n"
        "beq a0, t0, .Le_case_a\n"
        "li t0, 3\n"
        "beq a0, t0, .Le_case_b\n"
        "j .Le_case_c\n"

        // ==========================================
        // Mode 0: Positive Control Correct (Probe Taken)
        // ==========================================
        ".Le_pos_cor:\n"
        "li t3, 1\n"
        "jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n"
        "jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n"
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n"
        "jal t6, .Ltarget_e\n"
        "rdcycle a5\n"
        "sub a0, a5, a4\n"
        "j .Le_exit\n"

        // ==========================================
        // Mode 1: Positive Control Mispredict (Probe Taken)
        // ==========================================
        ".Le_pos_mis:\n"
        "li t3, 0\n"
        "jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n"
        "jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n"
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n"
        "jal t6, .Ltarget_e\n"
        "rdcycle a5\n"
        "sub a0, a5, a4\n"
        "j .Le_exit\n"

        // ==========================================
        // Mode 2: Condition A (Hit: 2 in-flight Taken, 0 intervening)
        // ==========================================
        ".Le_case_a:\n"
        // Train Not-Taken 8x
        "li t3, 0\n"
        "jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n"
        "jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n"
        // ROB stall: 4 dependent divs
        "li t4, 999999\n"
        "li t5, 7\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        // 2 in-flight Taken updates
        "li t3, 1\n"
        "jal t6, .Ltarget_e\n"
        "nop; nop;\n"
        "jal t6, .Ltarget_e\n"
        // Timed Probe Taken
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n"
        "jal t6, .Ltarget_e\n"
        "rdcycle a5\n"
        "sub a0, a5, a4\n"
        "j .Le_exit\n"

        // ==========================================
        // Mode 3: Condition B (Evict: 2 in-flight Taken, 3 intervening)
        // ==========================================
        ".Le_case_b:\n"
        // Train Not-Taken 8x
        "li t3, 0\n"
        "jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n"
        "jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n"
        // ROB stall: 4 dependent divs
        "li t4, 999999\n"
        "li t5, 7\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        // In-flight Taken update 1
        "li t3, 1\n"
        "jal t6, .Ltarget_e\n"
        // 3 intervening branches at distinct 16-byte aligned fetch packets
        ".balign 16\n"
        "bne x0, x0, 721f\n"
        "nop\n"
        "721:\n"
        ".balign 16\n"
        "bne x0, x0, 722f\n"
        "nop\n"
        "722:\n"
        ".balign 16\n"
        "bne x0, x0, 723f\n"
        "nop\n"
        "723:\n"
        // In-flight Taken update 2
        "jal t6, .Ltarget_e\n"
        // Timed Probe Taken
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n"
        "jal t6, .Ltarget_e\n"
        "rdcycle a5\n"
        "sub a0, a5, a4\n"
        "j .Le_exit\n"

        // ==========================================
        // Mode 4: Condition C (Outside-Window Control)
        // ==========================================
        ".Le_case_c:\n"
        // Train Not-Taken 8x
        "li t3, 0\n"
        "jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n"
        "jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n jal t6, .Ltarget_e\n"
        // ROB stall: 4 dependent divs
        "li t4, 999999\n"
        "li t5, 7\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        "div t4, t4, t5\n"
        // 2 in-flight Taken updates (0 intervening branches)
        "li t3, 1\n"
        "jal t6, .Ltarget_e\n"
        "nop; nop;\n"
        "jal t6, .Ltarget_e\n"
        // Settle pipeline
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        // 3 intervening branches executed outside window
        ".balign 16\n"
        "bne x0, x0, 731f\n"
        "nop\n"
        "731:\n"
        ".balign 16\n"
        "bne x0, x0, 732f\n"
        "nop\n"
        "732:\n"
        ".balign 16\n"
        "bne x0, x0, 733f\n"
        "nop\n"
        "733:\n"
        // Timed Probe Taken
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n"
        "jal t6, .Ltarget_e\n"
        "rdcycle a5\n"
        "sub a0, a5, a4\n"
        "j .Le_exit\n"

        // Target Branch
        ".balign 16\n"
        ".Ltarget_e:\n"
        "bnez t3, .Ltb_e_dest\n"
        "nop\n"
        ".Ltb_e_dest:\n"
        "jr t6\n"

        ".Le_exit:\n"
        : "=r"(reg_res)
        : "0"(r_mode)
        : "t0", "t3", "t4", "t5", "t6", "a4", "a5", "memory"
    );

    return reg_res;
}

#define EXP_TRIALS 20
static uint64_t ep_pos_cor[EXP_TRIALS];
static uint64_t ep_pos_mis[EXP_TRIALS];
static uint64_t ep_cond_a[EXP_TRIALS];
static uint64_t ep_cond_b[EXP_TRIALS];
static uint64_t ep_cond_c[EXP_TRIALS];

int main(void) {
    print_s("====================================================\n");
    print_s("WRBYPASS PREDICTOR EXPERIMENT: 20 TRIALS PER COND\n");
    print_s("====================================================\n\n");

    for (int t = 0; t < EXP_TRIALS; t++) {
        ep_pos_cor[t] = run_kernel_e(0);
        ep_pos_mis[t] = run_kernel_e(1);
        ep_cond_a[t]  = run_kernel_e(2);
        ep_cond_b[t]  = run_kernel_e(3);
        ep_cond_c[t]  = run_kernel_e(4);
    }

    // 1. Positive Control: Correct Prediction
    print_s("POSITIVE_CONTROL_CORRECT (Probe Taken, Expected ~27 cycles):\n");
    for (int i = 0; i < EXP_TRIALS; i++) {
        print_s(" ");
        print_u64(ep_pos_cor[i]);
    }
    print_s("\n\n");

    // 2. Positive Control: Deliberate Misprediction
    print_s("POSITIVE_CONTROL_MISPREDICT (Probe Taken, Expected ~35-37 cycles):\n");
    for (int i = 0; i < EXP_TRIALS; i++) {
        print_s(" ");
        print_u64(ep_pos_mis[i]);
    }
    print_s("\n\n");

    // 3. Condition A: wrbypass Hit
    print_s("CONDITION_A_HIT (Probe Taken, Expected ~27 cycles):\n");
    for (int i = 0; i < EXP_TRIALS; i++) {
        print_s(" ");
        print_u64(ep_cond_a[i]);
    }
    print_s("\n\n");

    // 4. Condition B: wrbypass Evict
    print_s("CONDITION_B_EVICT (Probe Taken, Expected ~35-37 cycles if evicted, ~27 if hit):\n");
    for (int i = 0; i < EXP_TRIALS; i++) {
        print_s(" ");
        print_u64(ep_cond_b[i]);
    }
    print_s("\n\n");

    // 5. Condition C: Outside-Window Control
    print_s("CONDITION_C_CONTROL (Probe Taken, Expected ~27 cycles):\n");
    for (int i = 0; i < EXP_TRIALS; i++) {
        print_s(" ");
        print_u64(ep_cond_c[i]);
    }
    print_s("\n\n");

    print_s("====================================================\n");
    print_s("EXPERIMENT COMPLETE\n");
    print_s("====================================================\n");

    tohost = 1;
    while (1) {}
    return 0;
}

