    uint64_t l = 0;
    for (int i = 0; i < 500; i++) {
        if (!s[i]) break;
        l++;
    }
    print_str(s, l);
}

static void print_u64(uint64_t val) {
    char buf[24];
    int idx = 0;
    if (val == 0) {
        buf[idx++] = '0';
    } else {
        char tmp[24];
        int tlen = 0;
        for (int i = 0; i < 20; i++) {
            if (val == 0) break;
            tmp[tlen++] = '0' + (val % 10);
            val /= 10;
        }
        for (int i = tlen - 1; i >= 0; i--) {
            buf[idx++] = tmp[i];
        }
    }
    print_str(buf, idx);
}

