        "rdcycle %0\n"
        "bne %2, x0, 1f\n"
        "nop; nop; nop; nop;\n"
        "1:\n"
        "rdcycle %1\n"
        : "=&r"(t0), "=&r"(t1)
        : "r"(cond)
    );
    return t1 - t0;
}

