#include <stdint.h>

extern volatile uint64_t tohost;
extern volatile uint64_t fromhost;

uint64_t _stack[512];
uint64_t * const _stack_top = _stack + 512;

#define SYS_write 64
static volatile uint64_t htif_payload[8] __attribute__((aligned(64)));

static void print_str(const char *s, uint64_t len) {
    for (int i = 0; i < 20000; i++) {
        if (tohost == 0) break;
    }
    htif_payload[0] = SYS_write;
    htif_payload[1] = 1;
    htif_payload[2] = (uint64_t)s;
    htif_payload[3] = len;
    tohost = (uint64_t)htif_payload;
    for (int i = 0; i < 20000; i++) {
        if (fromhost != 0) {
            fromhost = 0;
            break;
        }
    }
}

static void print_s(const char *s) {
    uint64_t l = 0;
    for (int i = 0; i < 500; i++) {
        if (!s[i]) break;
        l++;
    }
    print_str(s, l);
}

static void print_u64(uint64_t val) {
    char buf[24];
    int idx = 0;
    if (val == 0) {
        buf[idx++] = '0';
    } else {
        char tmp[24];
        int tlen = 0;
        for (int i = 0; i < 20; i++) {
            if (val == 0) break;
            tmp[tlen++] = '0' + (val % 10);
            val /= 10;
        }
        for (int i = tlen - 1; i >= 0; i--) {
            buf[idx++] = tmp[i];
        }
    }
    print_str(buf, idx);
}

// Positive Control Branch
__attribute__((noinline))
static uint64_t pos_ctrl_branch(int cond) {
    uint64_t t0, t1;
    asm volatile(
        "nop; nop; nop; nop;\n"
        "rdcycle %0\n"
        "bne %2, x0, 1f\n"
        "nop; nop; nop; nop;\n"
        "1:\n"
        "rdcycle %1\n"
        : "=&r"(t0), "=&r"(t1)
        : "r"(cond)
    );
    return t1 - t0;
}

static uint64_t pos_correct(void) {
    for (int i = 0; i < 30; i++) pos_ctrl_branch(1);
    return pos_ctrl_branch(1);
}

static uint64_t pos_mispredict(void) {
    for (int i = 0; i < 30; i++) pos_ctrl_branch(1);
    return pos_ctrl_branch(0);
}

// Unified Dual-Direction Kernel
// mode 0: Train Taken (12x), 2 in-flight Not-Taken (0 interv), Probe Taken
// mode 1: Train Taken (12x), 2 in-flight Not-Taken (3 interv), Probe Taken
// mode 2: Train Taken (12x), 2 in-flight Not-Taken, 3 interv outside, Probe Taken
// mode 3: Train Not-Taken (12x), 2 in-flight Taken (0 interv), Probe Taken
// mode 4: Train Not-Taken (12x), 2 in-flight Taken (3 interv), Probe Taken
// mode 5: Train Not-Taken (12x), 2 in-flight Taken, 3 interv outside, Probe Taken
__attribute__((noinline))
static uint64_t run_dual_kernel(int mode) {
    register uint64_t r_mode asm("a0") = mode;
    register uint64_t reg_res asm("a0");

    asm volatile(
        "li t0, 0\n beq a0, t0, .Ld_m0\n"
        "li t0, 1\n beq a0, t0, .Ld_m1\n"
        "li t0, 2\n beq a0, t0, .Ld_m2\n"
        "li t0, 3\n beq a0, t0, .Ld_m3\n"
        "li t0, 4\n beq a0, t0, .Ld_m4\n"
        "j .Ld_m5\n"

        // ==========================================
        // Mode 0: Train Taken 12x, 2 in-flight NT (0 interv), Probe Taken
        // ==========================================
        ".Ld_m0:\n"
        "li t3, 1\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        // ROB stall
        "li t4, 999999\n li t5, 7\n"
        "div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n"
        // 2 in-flight NT
        "li t3, 0\n"
        "jal t6, .Ltarget_d\n nop; nop;\n jal t6, .Ltarget_d\n"
        // Probe Taken
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n jal t6, .Ltarget_d\n rdcycle a5\n"
        "sub a0, a5, a4\n j .Ld_exit\n"

        // ==========================================
        // Mode 1: Train Taken 12x, 2 in-flight NT (3 interv), Probe Taken
        // ==========================================
        ".Ld_m1:\n"
        "li t3, 1\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        // ROB stall
        "li t4, 999999\n li t5, 7\n"
        "div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n"
        // 2 in-flight NT with 3 interv
        "li t3, 0\n"
        "jal t6, .Ltarget_d\n"
        ".balign 16\n bne x0, x0, 1001f\n nop\n 1001:\n"
        ".balign 16\n bne x0, x0, 1002f\n nop\n 1002:\n"
        ".balign 16\n bne x0, x0, 1003f\n nop\n 1003:\n"
        "jal t6, .Ltarget_d\n"
        // Probe Taken
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n jal t6, .Ltarget_d\n rdcycle a5\n"
        "sub a0, a5, a4\n j .Ld_exit\n"

        // ==========================================
        // Mode 2: Train Taken 12x, 2 in-flight NT, 3 interv OUTSIDE, Probe Taken
        // ==========================================
        ".Ld_m2:\n"
        "li t3, 1\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        // ROB stall
        "li t4, 999999\n li t5, 7\n"
        "div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n"
        // 2 in-flight NT
        "li t3, 0\n"
        "jal t6, .Ltarget_d\n nop; nop;\n jal t6, .Ltarget_d\n"
        // Settle pipeline
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        // 3 interv outside
        ".balign 16\n bne x0, x0, 1011f\n nop\n 1011:\n"
        ".balign 16\n bne x0, x0, 1012f\n nop\n 1012:\n"
        ".balign 16\n bne x0, x0, 1013f\n nop\n 1013:\n"
        // Probe Taken
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n jal t6, .Ltarget_d\n rdcycle a5\n"
        "sub a0, a5, a4\n j .Ld_exit\n"

        // ==========================================
        // Mode 3: Train Not-Taken 12x, 2 in-flight Taken (0 interv), Probe Taken
        // ==========================================
        ".Ld_m3:\n"
        "li t3, 0\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        // ROB stall
        "li t4, 999999\n li t5, 7\n"
        "div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n"
        // 2 in-flight Taken
        "li t3, 1\n"
        "jal t6, .Ltarget_d\n nop; nop;\n jal t6, .Ltarget_d\n"
        // Probe Taken
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n jal t6, .Ltarget_d\n rdcycle a5\n"
        "sub a0, a5, a4\n j .Ld_exit\n"

        // ==========================================
        // Mode 4: Train Not-Taken 12x, 2 in-flight Taken (3 interv), Probe Taken
        // ==========================================
        ".Ld_m4:\n"
        "li t3, 0\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        // ROB stall
        "li t4, 999999\n li t5, 7\n"
        "div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n"
        // 2 in-flight Taken with 3 interv
        "li t3, 1\n"
        "jal t6, .Ltarget_d\n"
        ".balign 16\n bne x0, x0, 1021f\n nop\n 1021:\n"
        ".balign 16\n bne x0, x0, 1022f\n nop\n 1022:\n"
        ".balign 16\n bne x0, x0, 1023f\n nop\n 1023:\n"
        "jal t6, .Ltarget_d\n"
        // Probe Taken
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n jal t6, .Ltarget_d\n rdcycle a5\n"
        "sub a0, a5, a4\n j .Ld_exit\n"

        // ==========================================
        // Mode 5: Train Not-Taken 12x, 2 in-flight Taken, 3 interv OUTSIDE, Probe Taken
        // ==========================================
        ".Ld_m5:\n"
        "li t3, 0\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        "jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n jal t6, .Ltarget_d\n"
        // ROB stall
        "li t4, 999999\n li t5, 7\n"
        "div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n"
        // 2 in-flight Taken
        "li t3, 1\n"
        "jal t6, .Ltarget_d\n nop; nop;\n jal t6, .Ltarget_d\n"
        // Settle pipeline
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        // 3 interv outside
        ".balign 16\n bne x0, x0, 1031f\n nop\n 1031:\n"
        ".balign 16\n bne x0, x0, 1032f\n nop\n 1032:\n"
        ".balign 16\n bne x0, x0, 1033f\n nop\n 1033:\n"
        // Probe Taken
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n jal t6, .Ltarget_d\n rdcycle a5\n"
        "sub a0, a5, a4\n j .Ld_exit\n"

        // Single Target Branch
        ".balign 16\n"
        ".Ltarget_d:\n"
        "bnez t3, .Ltb_d_dest\n"
        "nop\n"
        ".Ltb_d_dest:\n"
        "jr t6\n"

        ".Ld_exit:\n"
        : "=r"(reg_res)
        : "0"(r_mode)
        : "t0", "t3", "t4", "t5", "t6", "a4", "a5", "memory"
    );

    return reg_res;
}

#define D_TRIALS 20
static uint64_t arr_pc_cor[D_TRIALS];
static uint64_t arr_pc_mis[D_TRIALS];
static uint64_t arr_exp1_a[D_TRIALS];
static uint64_t arr_exp1_b[D_TRIALS];
static uint64_t arr_exp1_c[D_TRIALS];
static uint64_t arr_exp2_a[D_TRIALS];
static uint64_t arr_exp2_b[D_TRIALS];
static uint64_t arr_exp2_c[D_TRIALS];

int main(void) {
    print_s("====================================================\n");
    print_s("BOOM MEGA V3: SYSTEMATIC WRBYPASS EVALUATION\n");
    print_s("====================================================\n\n");

    // Positive Control
    for (int t = 0; t < D_TRIALS; t++) {
        arr_pc_cor[t] = pos_correct();
        arr_pc_mis[t] = pos_mispredict();
    }

    // Experiment 1 (Starting from Taken, 2 in-flight Not-Taken updates)
    for (int t = 0; t < D_TRIALS; t++) {
        arr_exp1_a[t] = run_dual_kernel(0);
        arr_exp1_b[t] = run_dual_kernel(1);
        arr_exp1_c[t] = run_dual_kernel(2);
    }

    // Experiment 2 (Starting from Not-Taken, 2 in-flight Taken updates)
    for (int t = 0; t < D_TRIALS; t++) {
        arr_exp2_a[t] = run_dual_kernel(3);
        arr_exp2_b[t] = run_dual_kernel(4);
        arr_exp2_c[t] = run_dual_kernel(5);
    }

    // Print all results
    print_s("POSITIVE_CONTROL_CORRECT:\n");
    for (int i = 0; i < D_TRIALS; i++) {
        print_s(" "); print_u64(arr_pc_cor[i]);
    }
    print_s("\n\n");

    print_s("POSITIVE_CONTROL_MISPREDICT:\n");
    for (int i = 0; i < D_TRIALS; i++) {
        print_s(" "); print_u64(arr_pc_mis[i]);
    }
    print_s("\n\n");

    print_s("EXP1_FROM_TAKEN_COND_A_HIT:\n");
    for (int i = 0; i < D_TRIALS; i++) {
        print_s(" "); print_u64(arr_exp1_a[i]);
    }
    print_s("\n\n");

    print_s("EXP1_FROM_TAKEN_COND_B_EVICT:\n");
    for (int i = 0; i < D_TRIALS; i++) {
        print_s(" "); print_u64(arr_exp1_b[i]);
    }
    print_s("\n\n");

    print_s("EXP1_FROM_TAKEN_COND_C_CONTROL:\n");
    for (int i = 0; i < D_TRIALS; i++) {
        print_s(" "); print_u64(arr_exp1_c[i]);
    }
    print_s("\n\n");

    print_s("EXP2_FROM_NOTTAKEN_COND_A_HIT:\n");
    for (int i = 0; i < D_TRIALS; i++) {
        print_s(" "); print_u64(arr_exp2_a[i]);
    }
    print_s("\n\n");

    print_s("EXP2_FROM_NOTTAKEN_COND_B_EVICT:\n");
    for (int i = 0; i < D_TRIALS; i++) {
        print_s(" "); print_u64(arr_exp2_b[i]);
    }
    print_s("\n\n");

    print_s("EXP2_FROM_NOTTAKEN_COND_C_CONTROL:\n");
    for (int i = 0; i < D_TRIALS; i++) {
        print_s(" "); print_u64(arr_exp2_c[i]);
    }
    print_s("\n\n");

    print_s("====================================================\n");
    print_s("EXPERIMENT COMPLETED\n");
    print_s("====================================================\n");

    tohost = 1;
    while (1) {}
    return 0;
}

void __attribute__((naked, section(".text.init"))) _start(void) {
    asm volatile(
        "la sp, _stack_top\n"
        "ld sp, 0(sp)\n"
        "tail main\n"
    );
}

