// Positive Control Branch
__attribute__((noinline))
static uint64_t pos_ctrl_branch(int cond) {
    uint64_t t0, t1;
    asm volatile(
        "nop; nop; nop; nop;\n"
        "rdcycle %0\n"
        "bne %2, x0, 1f\n"
        "nop; nop; nop; nop;\n"
        "1:\n"
        "rdcycle %1\n"
        : "=&r"(t0), "=&r"(t1)
