// Attack Kernel: Target Branch initially trained Not-Taken (12x)
// mode 0: Condition A (Hit: 2 in-flight Taken, 0 intervening branches)
// mode 1: Condition B (Evict: 2 in-flight Taken, 3 intervening branches)
// mode 2: Condition C (Negative Control: 2 in-flight Taken, 3 interv branches OUTSIDE window)
__attribute__((noinline))
static uint64_t run_exp2_kernel(int mode) {
    register uint64_t r_mode asm("a0") = mode;
    register uint64_t reg_res asm("a0");

    asm volatile(
        "li t0, 0\n beq a0, t0, .Lexp2_m0\n"
        "li t0, 1\n beq a0, t0, .Lexp2_m1\n"
        "j .Lexp2_m2\n"

        // ==========================================
        // Mode 0: Condition A (Hit: 0 intervening branches)
        // ==========================================
        ".Lexp2_m0:\n"
        // Train Not-Taken 12x
        "li t3, 0\n"
        "jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n"
        "jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n"
        "jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n"
        // ROB stall: 4 dependent divs
        "li t4, 999999\n li t5, 7\n"
        "div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n"
        // 2 in-flight Taken updates (0 intervening branches)
        "li t3, 1\n"
        "jal t6, .Ltarget_e2\n nop; nop;\n jal t6, .Ltarget_e2\n"
        // Timed Probe: Taken (t3 = 1)
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n jal t6, .Ltarget_e2\n rdcycle a5\n"
        "sub a0, a5, a4\n j .Lexp2_exit\n"

        // ==========================================
        // Mode 1: Condition B (Evict: 3 intervening branches)
        // ==========================================
        ".Lexp2_m1:\n"
        // Train Not-Taken 12x
        "li t3, 0\n"
        "jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n"
        "jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n"
        "jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n"
        // ROB stall: 4 dependent divs
        "li t4, 999999\n li t5, 7\n"
        "div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n"
        // In-flight Taken update 1
        "li t3, 1\n"
        "jal t6, .Ltarget_e2\n"
        // 3 intervening branches at distinct 16-byte aligned fetch packets
        ".balign 16\n bne x0, x0, 2001f\n nop\n 2001:\n"
        ".balign 16\n bne x0, x0, 2002f\n nop\n 2002:\n"
        ".balign 16\n bne x0, x0, 2003f\n nop\n 2003:\n"
        // In-flight Taken update 2
        "jal t6, .Ltarget_e2\n"
        // Timed Probe: Taken (t3 = 1)
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n jal t6, .Ltarget_e2\n rdcycle a5\n"
        "sub a0, a5, a4\n j .Lexp2_exit\n"

        // ==========================================
        // Mode 2: Condition C (Negative Control: 3 interv OUTSIDE window)
        // ==========================================
        ".Lexp2_m2:\n"
        // Train Not-Taken 12x
        "li t3, 0\n"
        "jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n"
        "jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n"
        "jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n jal t6, .Ltarget_e2\n"
        // ROB stall: 4 dependent divs
        "li t4, 999999\n li t5, 7\n"
        "div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n div t4, t4, t5\n"
        // 2 in-flight Taken updates
        "li t3, 1\n"
        "jal t6, .Ltarget_e2\n nop; nop;\n jal t6, .Ltarget_e2\n"
        // Settle pipeline
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        // 3 intervening branches executed OUTSIDE window
        ".balign 16\n bne x0, x0, 2011f\n nop\n 2011:\n"
        ".balign 16\n bne x0, x0, 2012f\n nop\n 2012:\n"
        ".balign 16\n bne x0, x0, 2013f\n nop\n 2013:\n"
        // Timed Probe: Taken (t3 = 1)
        "nop; nop; nop; nop; nop; nop; nop; nop;\n"
        "li t3, 1\n"
        "rdcycle a4\n jal t6, .Ltarget_e2\n rdcycle a5\n"
        "sub a0, a5, a4\n j .Lexp2_exit\n"

        // Single Target Branch
        ".balign 16\n"
        ".Ltarget_e2:\n"
        "bnez t3, .Ltb_e2_dest\n"
        "nop\n"
        ".Ltb_e2_dest:\n"
        "jr t6\n"

        ".Lexp2_exit:\n"
        : "=r"(reg_res)
        : "0"(r_mode)
        : "t0", "t3", "t4", "t5", "t6", "a4", "a5", "memory"
    );

    return reg_res;
}

#define TRIALS_N 20
static uint64_t p_cor[TRIALS_N];
static uint64_t p_mis[TRIALS_N];
static uint64_t c_hit[TRIALS_N];
static uint64_t c_evict[TRIALS_N];
static uint64_t c_ctrl[TRIALS_N];

int main(void) {
    print_s("====================================================\n");
    print_s("BOOM MEGA V3: SYSTEMATIC WRBYPASS EVALUATION REPORT\n");
    print_s("====================================================\n\n");

    // Phase 1: Positive Control
    for (int t = 0; t < TRIALS_N; t++) {
        p_cor[t] = pos_correct();
        p_mis[t] = pos_mispredict();
    }

    // Phase 2: Attack Conditions A, B, C
    for (int t = 0; t < TRIALS_N; t++) {
        c_hit[t]   = run_exp2_kernel(0);
        c_evict[t] = run_exp2_kernel(1);
        c_ctrl[t]  = run_exp2_kernel(2);
    }

    // Print all arrays
    print_s("POSITIVE_CONTROL_CORRECT (20 trials):\n");
    for (int i = 0; i < TRIALS_N; i++) {
        print_s(" "); print_u64(p_cor[i]);
    }
    print_s("\n\n");

    print_s("POSITIVE_CONTROL_MISPREDICT (20 trials):\n");
    for (int i = 0; i < TRIALS_N; i++) {
        print_s(" "); print_u64(p_mis[i]);
    }
    print_s("\n\n");

    print_s("CONDITION_A_HIT (wrbypass Hit, 0 intervening branches in-flight) [20 trials]:\n");
    for (int i = 0; i < TRIALS_N; i++) {
        print_s(" "); print_u64(c_hit[i]);
    }
    print_s("\n\n");

    print_s("CONDITION_B_EVICT (wrbypass Evict, 3 intervening branches in-flight) [20 trials]:\n");
    for (int i = 0; i < TRIALS_N; i++) {
        print_s(" "); print_u64(c_evict[i]);
    }
    print_s("\n\n");

    print_s("CONDITION_C_CONTROL (Negative Control, 3 intervening branches outside window) [20 trials]:\n");
    for (int i = 0; i < TRIALS_N; i++) {
        print_s(" "); print_u64(c_ctrl[i]);
    }
    print_s("\n\n");

    print_s("====================================================\n");
    print_s("EXPERIMENT COMPLETED SUCCESSFULLY\n");
    print_s("====================================================\n");

    tohost = 1;
    while (1) {}
    return 0;
}

void __attribute__((naked, section(".text.init"))) _start(void) {
    asm volatile(
        "la sp, _stack_top\n"
        "ld sp, 0(sp)\n"
        "tail main\n"
    );
